namespace Full.NET.Modules.Ai.Persistence;

/// <summary>文档与版本共用两层读取条件；每层可以匹配用户或权威活动角色，两层必须同时满足。</summary>
internal static class AiKnowledgeReadSql
{
    internal const string Layers = "(knowledge.OwnerUserId = @OwnerUserId OR ((EXISTS (SELECT 1 FROM fn_ai_knowledge_member AS baseMember WHERE baseMember.KnowledgeBaseId = knowledge.Id AND baseMember.UserId = @OwnerUserId) OR EXISTS (SELECT 1 FROM fn_ai_knowledge_role AS baseRole WHERE baseRole.KnowledgeBaseId = knowledge.Id AND baseRole.RoleId IN (SELECT RoleId FROM OPENJSON(@ActiveRoleIdsJson) WITH (RoleId uniqueidentifier '$')))) AND (EXISTS (SELECT 1 FROM fn_ai_knowledge_document_member AS docMember WHERE docMember.DocumentId = document.Id AND docMember.UserId = @OwnerUserId) OR EXISTS (SELECT 1 FROM fn_ai_knowledge_document_role AS docRole WHERE docRole.DocumentId = document.Id AND docRole.RoleId IN (SELECT RoleId FROM OPENJSON(@ActiveRoleIdsJson) WITH (RoleId uniqueidentifier '$'))))))";
    internal const string LayersMySql = "(knowledge.OwnerUserId = @OwnerUserId OR ((EXISTS (SELECT 1 FROM fn_ai_knowledge_member AS baseMember WHERE baseMember.KnowledgeBaseId = knowledge.Id AND baseMember.UserId = @OwnerUserId) OR EXISTS (SELECT 1 FROM fn_ai_knowledge_role AS baseRole WHERE baseRole.KnowledgeBaseId = knowledge.Id AND baseRole.RoleId IN (SELECT UUID_TO_BIN(activeRole.Id, 0) FROM JSON_TABLE(@ActiveRoleIdsJson, '$[*]' COLUMNS (Id CHAR(36) PATH '$')) AS activeRole))) AND (EXISTS (SELECT 1 FROM fn_ai_knowledge_document_member AS docMember WHERE docMember.DocumentId = document.Id AND docMember.UserId = @OwnerUserId) OR EXISTS (SELECT 1 FROM fn_ai_knowledge_document_role AS docRole WHERE docRole.DocumentId = document.Id AND docRole.RoleId IN (SELECT UUID_TO_BIN(activeRole.Id, 0) FROM JSON_TABLE(@ActiveRoleIdsJson, '$[*]' COLUMNS (Id CHAR(36) PATH '$')) AS activeRole)))))";
}
